"""Writes lucide.ts: the Lucide icons the gallery draws, as typed data.

Usage: python3 -I scripts/lucide.py <icon-nodes.json> [version]

`icon-nodes.json` is lucide-static's `{name: [[tag, attrs], ...]}`. Only the
icons in ICONS are written, so the bundle carries what the gallery shows.
"""

import json
import pathlib
import sys

# The icons the gallery uses, by Lucide name.
ICONS = [
    "activity", "arrow-down", "arrow-up", "at-sign", "atom", "bell", "blocks", "bold",
    "chart-candlestick", "check", "chevron-left", "chevron-right", "circle-play", "code",
    "database", "file-text", "hand", "heading-1", "heading-2", "heading-3", "image", "images",
    "italic", "layers", "link", "list", "list-indent-decrease", "list-indent-increase",
    "list-ordered", "message-circle", "minus", "moon", "palette", "panel-bottom",
    "panel-left", "pause", "pencil", "pilcrow", "play", "plus", "redo-2", "replace",
    "replace-all", "scroll-text", "search", "send-horizontal", "settings",
    "sliders-horizontal", "smartphone", "sparkles", "square-code", "star",
    "strikethrough", "sun", "text-cursor-input", "text-quote", "toggle-right",
    "triangle-alert", "type", "underline", "undo-2", "wind", "x",
    # The Rich Editor demo's zoom, links and tables.
    "maximize-2", "minimize-2", "unlink", "external-link", "table",
    "between-horizontal-start", "between-horizontal-end", "between-vertical-start",
    "between-vertical-end", "table-cells-merge", "table-cells-split", "trash",
    "grip-vertical", "grip-horizontal", "panel-top", "list-todo", "ellipsis",
]

# The attributes each element's drawing reads.
ATTRS = {
    "path": ["d"],
    "circle": ["cx", "cy", "r"],
    "ellipse": ["cx", "cy", "rx", "ry"],
    "rect": ["x", "y", "width", "height", "rx"],
    "line": ["x1", "y1", "x2", "y2"],
    "polyline": ["points"],
    "polygon": ["points"],
}


def element(tag, attrs):
    out = {"tag": tag}
    for name in ATTRS[tag]:
        if name in attrs:
            value = attrs[name]
            out[name] = value if name in ("d", "points") else float(value)
    return out


def main():
    nodes = json.loads(pathlib.Path(sys.argv[1]).read_text())
    version = sys.argv[2] if len(sys.argv) > 2 else "1.61.0"
    missing = [name for name in ICONS if name not in nodes]
    if missing:
        sys.exit(f"not in Lucide {version}: {', '.join(missing)}")
    lines = [
        f"// Generated by scripts/lucide.py from lucide-static {version}: do not edit.",
        "// Lucide (https://lucide.dev), ISC License, Copyright (c) Lucide Contributors.",
        "",
        "/** One element of a Lucide icon, on its 24 × 24 grid. */",
        "export type LucideElement =",
        '  | { tag: "path"; d: string }',
        '  | { tag: "circle"; cx: number; cy: number; r: number }',
        '  | { tag: "ellipse"; cx: number; cy: number; rx: number; ry: number }',
        '  | { tag: "rect"; x: number; y: number; width: number; height: number; rx?: number }',
        '  | { tag: "line"; x1: number; y1: number; x2: number; y2: number }',
        '  | { tag: "polyline" | "polygon"; points: string };',
        "",
        "export const lucide = {",
    ]
    for name in sorted(ICONS):
        elements = [element(tag, attrs) for tag, attrs in nodes[name]]
        lines.append(f"  {json.dumps(name)}: {json.dumps(elements, separators=(', ', ': '))},")
    lines += [
        "} satisfies Record<string, LucideElement[]>;",
        "",
        "/** The name of an icon the gallery draws. */",
        "export type LucideName = keyof typeof lucide;",
        "",
    ]
    out = pathlib.Path(__file__).resolve().parent.parent / "lucide.ts"
    out.write_text("\n".join(lines))


main()
